// Punto unico donde queda resuelto el subscriber_id, sin importar si el contacto
// se acaba de crear o si ya existia.
//
// OJO: los dos endpoints devuelven shapes DISTINTOS --
//   createSubscriber    -> data: { id: ... }        (objeto)
//   findBySystemField   -> data: [ { id: ... } ]    (array)
// De ahi el chequeo de Array.isArray.
//
// Existe para que setCustomFields y sendFlow tengan UN solo nombre de nodo al que
// referenciar, en vez de ramificar la expresion segun por que camino vino el contacto.
const r = $json;
const d = r?.data;
const id = Array.isArray(d) ? d?.[0]?.id : d?.id;

if (!id) {
  // No deberia pasar: las compuertas de arriba ya filtran los casos sin subscriber.
  // Si igual llega aca, se corta SOLO este contacto en vez de abortar el batch entero.
  return [{ json: { _error: true, _detalle: JSON.stringify(r) } }];
}

return [{ json: { subscriber_id: String(id) } }];
